TWLBG_DIR = os.path.join('sd', '_nds', 'TWiLightMenu', 'TwlBg')
WIDE_DIR = os.path.join('sd', '_nds', 'TWiLightMenu', 'extras', 'widescreen')


def base_dir():
    if getattr(sys, 'frozen', False):
        return os.path.dirname(os.path.abspath(sys.executable))
    here = os.path.dirname(os.path.abspath(__file__))
    up = os.path.dirname(here)
    return up if os.path.isdir(os.path.join(up, 'sd')) else here


def say(*a):
    s = ' '.join(str(x) for x in a)
    try:
        print(s)
    except UnicodeEncodeError:
        print(s.encode('ascii', 'replace').decode())
    sys.stdout.flush()


def blz_decompress(data):
    """3DS ExeFS .code backward LZ"""
    data = bytearray(data)
    top_bottom, extra = struct.unpack_from('<II', data, len(data) - 8)
    enc_size, header_len = top_bottom & 0xFFFFFF, top_bottom >> 24
    out = bytearray(len(data) + extra)
    out[:len(data)] = data
    src, end, dst = len(data) - header_len, len(data) - enc_size, len(out)
    while src > end:
        src -= 1
        flags = out[src]
        for _ in range(8):
            if src <= end: break
            if flags & 0x80:
                src -= 2
                v = out[src] | (out[src + 1] << 8)
                disp = (v & 0xFFF) + 3
                for _ in range((v >> 12) + 3):
                    dst -= 1
                    out[dst] = out[dst + disp]
            else:
                src -= 1; dst -= 1
                out[dst] = out[src]
            flags = (flags << 1) & 0xFF
    return bytes(out)


def write(rel, data, src):
    p = os.path.join(base_dir(), rel)
    if os.path.abspath(p).lower() == os.path.abspath(src).lower():
        say('  [실패] 넣은 파일이 결과가 저장될 자리에 있습니다. 파일을 다른 폴더로 옮긴 뒤 다시 넣어 주세요.')
        return False
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'wb') as f: f.write(data)
    say('  [완료] ' + p)
    return True


def do_cxi(path, d):
    try:
        eo = struct.unpack_from('<I', d, 0x1A0)[0] * 0x200                  # ExeFS
        name, off, size = struct.unpack_from('<8sII', d, eo)
        assert name.rstrip(b'\0') == b'.code'
        raw = d[eo + 0x200 + off:eo + 0x200 + off + size]
        code = blz_decompress(raw) if d[0x200 + 0xD] & 1 else raw
    except Exception:
        say('  [실패] .cxi 파일을 읽을 수 없습니다.'); return False
    h = hashlib.sha256(code).hexdigest()
    if h == OUT_CODE_SHA256:
        say('  [그대로] 이 파일은 이미 3D 용입니다. 고치기 전의 TWPatch 파일을 넣어 주세요.'); return False
    if h != BASE_CODE_SHA256:
        say('  [실패] 지원하는 TwlBg 빌드가 아닙니다 (코드 sha256 %s...).' % h[:16])
        say('         시스템 버전, TWPatch 버전이나 옵션이 다르면 빌드가 달라집니다. 아무것도 쓰지 않았습니다.'); return False
    code = bytearray(code)
    for o, hx in CXI_PATCH:
        b = bytes.fromhex(hx); code[o:o + len(b)] = b
    code = bytes(code)
    assert hashlib.sha256(code).hexdigest() == OUT_CODE_SHA256
    pad = (len(code) + 0x1FF) & ~0x1FF
    hdr = bytearray(0x200)
    hdr[0:8] = b'.code\0\0\0'
    struct.pack_into('<II', hdr, 8, 0, len(code))
    hdr[0xC0 + 9 * 0x20:0xC0 + 10 * 0x20] = hashlib.sha256(code).digest()
    out = bytearray(d[:eo]) + hdr + code + bytes(pad - len(code))
    out[0x200 + 0xD] &= ~1                                                 # exheader: code not compressed
    out[0x160:0x180] = hashlib.sha256(out[0x200:0x600]).digest()           # exheader hash
    struct.pack_into('<I', out, 0x1A4, (0x200 + pad) // 0x200)             # ExeFS size
    struct.pack_into('<I', out, 0x1A8, 1)                                  # ExeFS hash region
    out[0x1C0:0x1E0] = hashlib.sha256(out[eo:eo + 0x200]).digest()
    struct.pack_into('<I', out, 0x104, len(out) // 0x200)                  # content size
    if not write(os.path.join(TWLBG_DIR, 'Widescreen.cxi'), out, path): return False
    if hashlib.sha256(out).hexdigest() == REF_CXI_SHA256: say('         기준 파일과 완전히 같습니다.')
    return True


def do_analog(path, pairs):
    code = bytearray(b''.join(struct.pack('<II', int(a, 16), int(b, 16)) for a, b in pairs))
    if hashlib.sha256(code).hexdigest() != ANALOG_SHA256:
        say('  [실패] 예상한 코드가 아닙니다 (코드 %d 줄, 351 줄이어야 함).' % len(pairs))
        say('         "ASMK-3C73EADE (Korea v1.0) [with Nub stick, ZL and ZR].txt" 를 그대로 넣어 주세요.'); return False
    for o, hx in ANALOG_PATCH:
        b = bytes.fromhex(hx); code[o:o + len(b)] = b
    out = bytes.fromhex(ENGINE_HEX) + bytes(code)
    assert hashlib.sha256(out).hexdigest() == ASMK_OUT_SHA256
    return write(os.path.join(WIDE_DIR, 'ASMK-53AF.bin'), out, path)


def handle(path):
    say(os.path.basename(path))
    try:
        d = open(path, 'rb').read()
    except OSError as e:
        say('  [실패] 파일을 열 수 없습니다: %s' % e); return False
    if d[0x100:0x104] == b'NCCH':
        return do_cxi(path, d)
    pairs = re.findall(r'^\s*([0-9A-Fa-f]{8})\s+([0-9A-Fa-f]{8})\s*$', d[:200000].decode('utf-8', 'replace'), re.M)
    if pairs:
        return do_analog(path, pairs)
    say('  [실패] 알 수 없는 파일입니다. Widescreen.cxi 또는 shocoman 의 코드 .txt 를 넣어 주세요.')
    return False


def main():
    args = [a for a in sys.argv[1:] if a != '--no-pause']
    pause = getattr(sys, 'frozen', False) and '--no-pause' not in sys.argv
    if not args:                                    # 더블클릭: 같은 폴더에 놓인 파일을 찾는다
        b = base_dir()
        args = [os.path.join(b, n) for n in sorted(os.listdir(b))
                if n.lower() in ('widescreen.cxi', 'twlbg.cxi') or (n.upper().startswith('ASMK-3C73EADE') and n.lower().endswith('.txt'))]
    if not args:
        say(__doc__)
        ok = False
    else:
        res = [handle(a) for a in args]
        ok = all(res)
        if any(res):
            say('')
            say('다음: ' + os.path.join(base_dir(), 'sd') + ' 안의 _nds 폴더를 SD 카드 최상위에 복사(덮어쓰기)하세요.')
    if pause:
        say('')
        try: input('Enter 키를 누르면 닫힙니다.')
        except EOFError: pass
    return 0 if ok else 1


if __name__ == '__main__':
    sys.exit(main())
